  el('path',{d:'M300 245 L282 280 L318 280Z',fill:'var(--muted)'},Bt);const bL=t_(Bt,300,320,'',{'text-anchor':'middle','font-size':15,'font-weight':700});const bN=t_(Bt,300,345,'',{'text-anchor':'middle','font-size':12});
